INSERT INTO `business_rules` VALUES (1,'asset_must_be_available','Asset must be Available','Asset inventory_state must be available before allocation-like actions','inventory','validation','{\"op\": \"eq\", \"path\": \"asset.inventory_state\", \"value\": \"available\"}','Asset must be Available',1,10,'2026-08-07 10:02:47','2026-08-07 10:02:47'),(2,'employee_must_be_active','Employee must be Active','Employee activated flag must be 1','employees','validation','{\"op\": \"eq\", \"path\": \"employee.activated\", \"value\": 1}','Employee must be Active',1,20,'2026-08-07 10:02:47','2026-08-07 10:02:47'),(3,'department_must_exist','Department must exist','Department id must resolve','organization','validation','{\"op\": \"exists\", \"path\": \"department.id\"}','Department must exist',1,30,'2026-08-07 10:02:47','2026-08-07 10:02:47'),(4,'warranty_dates_valid','Warranty dates valid','Warranty start cannot be after end','assets','validation','{\"op\": \"date_lte\", \"path_a\": \"asset.warranty_start\", \"path_b\": \"asset.warranty_end\"}','Warranty cannot start after end date',1,40,'2026-08-07 10:02:47','2026-08-07 10:02:47'),(5,'prevent_invalid_transition','Prevent invalid workflow transition','Transition must exist on definition for current state','workflow','transition','{\"op\": \"workflow_transition_allowed\"}','Invalid workflow transition',1,5,'2026-08-07 10:02:47','2026-08-07 10:02:47');
