  `department_name` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `business_line` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `designation` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `grade_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `supervisor_employee_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pan_number` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `personal_email` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mobile` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `work_mobile` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `office_location` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `employee_pincode` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `employment_status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `employment_status_description` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `employee_status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `employee_status_description` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `emp_added_on` datetime DEFAULT NULL,
  `refex_company_name` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `refex_location` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
