  KEY `idx_employees_deleted` (`deleted_at`),
  KEY `idx_employees_name` (`last_name`,`first_name`)
) ENGINE=InnoDB AUTO_INCREMENT=2254 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
