--
-- Table structure for table `event_subscriptions`
--

DROP TABLE IF EXISTS `event_subscriptions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `event_subscriptions` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(96) COLLATE utf8mb4_unicode_ci NOT NULL,
  `event_type` varchar(96) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '*',
  `handler_key` varchar(96) COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `config` json DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_event_sub_name_type` (`name`,`event_type`),
  KEY `idx_event_sub_type` (`event_type`,`is_active`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

