DROP TABLE IF EXISTS `notification_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notification_log` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `kind` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `item_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `item_id` int unsigned NOT NULL,
  `notified_on` date NOT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_notification_log_day` (`kind`,`item_type`,`item_id`,`notified_on`),
  KEY `idx_notification_log_kind_day` (`kind`,`notified_on`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

