,'{\"op\": \"always\"}','allow','{\"flags\": {\"auto_progress\": true, \"requires_acceptance\": true}, \"attach_sla\": [{\"clock_start\": \"now\", \"definition_code\": \"transfer.completion\"}]}','Standard transfer allowed','2026-08-07 10:32:41','2026-08-07 10:33:18');
