--
-- Table structure for table `users`
--

DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `users` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `employee_num` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `employee_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `first_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `last_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `username` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `password` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `phone` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `jobtitle` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `designation` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `grade` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `locale` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'en-US',
  `timezone` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `company_id` int unsigned DEFAULT NULL,
  `legal_entity_id` int unsigned DEFAULT NULL,
  `business_line_id` int unsigned DEFAULT NULL,
  `location_id` int unsigned DEFAULT NULL,
  `department_id` int unsigned DEFAULT NULL,
  `manager_id` int unsigned DEFAULT NULL,
  `activated` tinyint(1) NOT NULL DEFAULT '1',
  `employment_status` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `employment_status_desc` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `joining_date` date DEFAULT NULL,
  `exit_date` date DEFAULT NULL,
  `last_sync_at` datetime DEFAULT NULL,
  `hr_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sync_status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'pending',
  `permissions` json DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `avatar` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `last_login` datetime DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_users_username` (`username`),
  KEY `idx_users_email` (`email`),
  KEY `idx_users_company` (`company_id`),
  KEY `idx_users_location` (`location_id`),
  KEY `idx_users_department` (`department_id`),
  KEY `idx_users_activated` (`activated`),
  KEY `idx_users_deleted` (`deleted_at`),
  KEY `fk_users_manager` (`manager_id`),
  KEY `idx_users_legal_entity` (`legal_entity_id`),
  KEY `idx_users_business_line` (`business_line_id`),
  KEY `idx_users_employee_code` (`employee_code`),
  KEY `idx_users_employment_status` (`employment_status`),
  CONSTRAINT `fk_users_business_line` FOREIGN KEY (`business_line_id`) REFERENCES `business_lines` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_users_company` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_users_department` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_users_legal_entity` FOREIGN KEY (`legal_entity_id`) REFERENCES `legal_entities` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_users_location` FOREIGN KEY (`location_id`) REFERENCES `locations` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_users_manager` FOREIGN KEY (`manager_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `users`
--

LOCK TABLES `users` WRITE;
/*!40000 ALTER TABLE `users` DISABLE KEYS */;
